def coin_change_brute(coins, amount):
    if amount == 0:
        return 0
    best = float('inf')
    for c in coins:
        if c <= amount:
            sub = coin_change_brute(coins, amount - c)          # try EVERY coin
            if sub != float('inf'):
                best = min(best, sub + 1)
    return best

