int coinChange(vector<int>& coins, int amount) {
    vector<int> dp(amount + 1, INT_MAX / 2);
    dp[0] = 0;
    for (int a = 1; a <= amount; a++) {
        for (int c : coins) {
            if (c <= a) dp[a] = min(dp[a], dp[a - c] + 1);                // best of using coin c here
        }
    }
    return dp[amount] >= INT_MAX / 2 ? -1 : dp[amount];
}
